// Max4Live number of input paramters we'll take in and pass to our Rust code
inlets = 6
outlets = 3

// Max4Live inlet variables
let inlet_0 = -1;  // Default value for first parameter (root note)
let inlet_1 = 0;  // Default value for second parameter (note offset)
let inlet_2 = 0;  // Default value for third parameter (velocity)
let inlet_3 = 120;  // Default value for fourth parameter (rate)
let inlet_4 = 0;  // Default value for fifth parameter (reserved)
let inlet_5 = 0;  // Default value for sixth parameter (reserved)
let kasm_rust = null;   // catch the wasm jump func ptr
let wasm_exports = null; // Global reference to WASM exports for memory access
let testFlipFlop = false;

// Helper function to get string from WASM memory
function getStringFromWasm0(ptr, len) {
    // Check if wasm_exports is available, if not, fallback to a simple string
    if (typeof wasm_exports === 'undefined' || !wasm_exports || !wasm_exports.memory) {
        return "WASM memory not available";
    }
    const mem = new Uint8Array(wasm_exports.memory.buffer);

    // Check if TextDecoder is available, if not use fallback implementation
    if (typeof TextDecoder !== 'undefined') {
        return new TextDecoder('utf-8', { ignoreBOM: true, fatal: true }).decode(mem.subarray(ptr, ptr + len));
    } else {
        // Fallback UTF-8 decoder for V8 environments without TextDecoder
        const bytes = mem.subarray(ptr, ptr + len);
        let result = '';
        let i = 0;

        while (i < bytes.length) {
            let byte1 = bytes[i++];

            if (byte1 < 0x80) {
                // 1-byte character (ASCII)
                result += String.fromCharCode(byte1);
            } else if (byte1 < 0xC0) {
                // Invalid UTF-8 start byte
                result += '\uFFFD'; // replacement character
            } else if (byte1 < 0xE0) {
                // 2-byte character
                if (i >= bytes.length) break;
                let byte2 = bytes[i++];
                if ((byte2 & 0xC0) !== 0x80) {
                    result += '\uFFFD';
                    i--; // back up one byte
                } else {
                    result += String.fromCharCode(((byte1 & 0x1F) << 6) | (byte2 & 0x3F));
                }
            } else if (byte1 < 0xF0) {
                // 3-byte character
                if (i + 1 >= bytes.length) break;
                let byte2 = bytes[i++];
                let byte3 = bytes[i++];
                if ((byte2 & 0xC0) !== 0x80 || (byte3 & 0xC0) !== 0x80) {
                    result += '\uFFFD';
                    i -= 2; // back up
                } else {
                    result += String.fromCharCode(((byte1 & 0x0F) << 12) | ((byte2 & 0x3F) << 6) | (byte3 & 0x3F));
                }
            } else if (byte1 < 0xF8) {
                // 4-byte character (needs surrogate pairs for JavaScript)
                if (i + 2 >= bytes.length) break;
                let byte2 = bytes[i++];
                let byte3 = bytes[i++];
                let byte4 = bytes[i++];
                if ((byte2 & 0xC0) !== 0x80 || (byte3 & 0xC0) !== 0x80 || (byte4 & 0xC0) !== 0x80) {
                    result += '\uFFFD';
                    i -= 3; // back up
                } else {
                    let codepoint = ((byte1 & 0x07) << 18) | ((byte2 & 0x3F) << 12) | ((byte3 & 0x3F) << 6) | (byte4 & 0x3F);
                    if (codepoint > 0x10FFFF) {
                        result += '\uFFFD';
                    } else {
                        // Convert to surrogate pair
                        codepoint -= 0x10000;
                        result += String.fromCharCode(0xD800 + (codepoint >> 10));
                        result += String.fromCharCode(0xDC00 + (codepoint & 0x3FF));
                    }
                }
            } else {
                // Invalid UTF-8 start byte
                result += '\uFFFD';
            }
        }

        return result;
    }
}

/**
 * Decodes a base64 string to a binary string (custom implementation for environments without window.atob).
 * @param {string} base64 - The base64-encoded string.
 * @returns {string} The decoded binary string.
 */
function atob(base64) {
    base64 = base64.replace(/=+$/, '');
    const chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';
    let str = '';
    let buffer = 0;
    let bits = 0;

    for (let i = 0; i < base64.length; i++) {
        const c = base64.charAt(i);
        const val = chars.indexOf(c);
        if (val === -1) continue; // Ignore invalid characters

        buffer = (buffer << 6) | val;
        bits += 6;

        if (bits >= 8) {
            bits -= 8;
            str += String.fromCharCode((buffer >> bits) & 0xFF);
        }
    }
    return str;
}

/**
 * Loads the base64-encoded WASM, decodes it, compiles it, and returns the result of calling the exported WASM function.
 * @returns {Promise<number>} The result of the WASM function, clamped to MIDI range (0-127).
 */
function kasm_WASM_rust() {
    // Base64-encoded WASM generated from Rust (kasm_ableton_rust_bg.wasm)
    const wasm_base64 = "";

    const wasm_buffer = Uint8Array.from(atob(wasm_base64), c => c.charCodeAt(0)).buffer;
    post("kasm_WASM_rust_obs: wasm_buffer=" + wasm_buffer);

    return WebAssembly.compile(wasm_buffer).then(module => {
        post("kasm_WASM_rust_obs: RUNNING");

        // these are the callback handlers from Rust code to make JavaScript calls
        const imports = {
            wbg: {
                __wbg_outlet_5ed60edbb924e29f: function(outlet_num, note, velocity, delay_ms) {
                    // V8 in Max/MSP doesn't have setTimeout, so we'll use Max's task system
                    if (delay_ms <= 0) {
                        // If delay is 0 or negative, call immediately
                        if (typeof outlet === 'function') {
                            outlet(outlet_num, note, velocity);
                        } else {
                            post("outlet(" + outlet_num + ", " + note + ", " + velocity + ")");
                        }
                    } else {
                        // Use Max's task system for delayed execution
                        if (typeof Task !== 'undefined') {
                            var task = new Task(function() {
                                if (typeof outlet === 'function') {
                                    outlet(outlet_num, note, velocity);
                                } else {
                                    post("delayed outlet(" + outlet_num + ", " + note + ", " + velocity + ") after " + delay_ms + "ms");
                                }
                            });
                            task.schedule(delay_ms);
                        } else {
                            // Fallback: call immediately if Task is not available
                            post("Warning: No timing mechanism available, calling immediately");
                            if (typeof outlet === 'function') {
                                outlet(outlet_num, note, velocity);
                            } else {
                                post("outlet(" + outlet_num + ", " + note + ", " + velocity + ")");
                            }
                        }
                    }
                },
                __wbg_post_d572083291db089b: function(arg0, arg1) {
                    // Safety check to ensure post function exists
                    if (typeof post === 'function') {
                        post(getStringFromWasm0(arg0, arg1));
                    } else {
                        // Fallback for environments where post is not available
                        console.log("post: " + getStringFromWasm0(arg0, arg1));
                    }
                },
                __wbindgen_init_externref_table: function() {
                    const table = wasm_exports.__wbindgen_export_0;
                    const offset = table.grow(4);
                    table.set(0, undefined);
                    table.set(offset + 0, undefined);
                    table.set(offset + 1, null);
                    table.set(offset + 2, true);
                    table.set(offset + 3, false);
                }
            }
        };

        const instance = new WebAssembly.Instance(module, imports);
        wasm_exports = instance.exports; // Set global reference immediately

        // Call the wasm-bindgen start function if it exists
        if (wasm_exports.__wbindgen_start) {
            wasm_exports.__wbindgen_start();
        }

        // Try to call the correct exported function (update as needed)
        if (instance.exports.kasm_midi_note_offset) {
            kasm_rust = instance.exports;
        } else {
            throw new Error("No known exported function found in WASM module");
        }
    });
}

function panic() {
    for (var note = 0; note < 128; note++) {
        outlet(0, note, 0);
    }
}

// Max4Live inlet handlers
function msg_int(value) {
    switch (inlet) {
        case 0:
            inlet_0 = value;
            break;
        case 1:
            inlet_1 = value;
            panic();
            break;
        case 2:
            inlet_2 = value;
            break;
        case 3:
            inlet_3 = value;
            panic();
            break;
        case 4:
            inlet_4 = value;
            panic();
            break;
        case 5:
            inlet_5 = value;
            panic();
            break;
    }
}

function loadbang() {
    kasm_WASM_rust().then(result => {
        post("Kasm WASM loaded successfully");
    }).catch(error => {
        post("Error when calling kasm_WASM_rust_obs(): " + error);
    });

    panic();
}

/**
 * Example function for Max/MSP integration. Calls the WASM function and outputs the result.
 */
function bang() {
    if (!kasm_rust) {
        loadbang();
        return;
    }

    // Call the Rust code to do it's magic
    kasm_rust.bang(inlet_0, inlet_1, inlet_2, inlet_3, inlet_4, inlet_5);
}
